@startuml

class Ingredient {
  + Name : string
  + MeasuringUnit : string
  + QuantityInStock : float
}

class Dish {
  + Name : string
  + Identifier : int
}

class Recipe {
  + Quantity : float
}

class Table {
  + Identifier : int
  + MaxPeople : int
}

class Meal {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Waiter {
  + Identifier : int
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Client {
  + TaxIdentificationNumber : string
  + Name : string
  + Address : string
}

class MealDish {
  + Quantity : float
}

Dish "1" *-- "1..*" Recipe : composed of
Recipe "1" -- "1" Ingredient : uses

Table "1" -- "*" Meal : hosts
Waiter "1" -- "*" Meal : responsible for
Client "0..1" -- "*" Meal : consumes
Meal "1" *-- "*" MealDish : contains
MealDish "*" -- "1" Dish : refers to

@enduml

